// Тест 1: Код ответа 200
pm.test("Код ответа 200", function () {
    pm.response.to.have.status(200);
});

// Тест 2: Время ответа < 500 мс
pm.test("Время ответа < 500 мс", function () {
    pm.expect(pm.response.responseTime).to.be.below(500);
});

// Тест 3: Ответ — непустой массив
pm.test("Ответ — непустой массив", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.be.an("array");
    pm.expect(jsonData).to.have.lengthOf.at.least(1);
});

// Тест 4: У первого элемента есть поля id, name, status
pm.test("У первого элемента есть поля id, name, status", function () {
    const jsonData = pm.response.json();
    const first = jsonData[0];
    pm.expect(first).to.have.property("id");
    pm.expect(first).to.have.property("name");
    pm.expect(first).to.have.property("status");
});

// Тест 5: id — число, name — строка
pm.test("id — число, name — строка", function () {
    const jsonData = pm.response.json();
    const first = jsonData[0];
    pm.expect(first.id).to.be.a("number");
    pm.expect(first.name).to.be.a("string");
});

// Сохраняем id первого корабля в переменную
const jsonData = pm.response.json();
pm.environment.set("ship_id", jsonData[0].id);

// Генерируем уникальный токен на основе времени и случайного числа
const generatedToken = `qa-token-${Date.now()}-${Math.floor(Math.random() * 1000000)}`;

// Сохраняем в переменную окружения
pm.environment.set("token", generatedToken);

// Выводим в консоль для проверки (как на скриншоте)
console.log("Generated token: ", generatedToken);

const name = `QA Ship ${Date.now()}_${Math.floor(Math.random() * 10000)}`;
pm.environment.set("starship_name", name);
console.log("Generated starship name: ", name);

pm.test("Status code is 201 or 400", () => {
    pm.expect(pm.response.code).to.be.oneOf([201, 400]);
});

if (pm.response.code === 201) {
    const response = pm.response.json();
    pm.environment.set("starship_id", response.id);
}

pm.test("Response has detail field if 400", () => {
    if (pm.response.code === 400) {
        pm.expect(pm.response.json()).to.have.property("detail");
    }
});

pm.test("Status 200 for successful update", () => {
    pm.response.to.have.status(200);
});

pm.test("Response contains updated starship data", () => {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("id");
    pm.expect(jsonData.name).to.be.a("string");
    pm.expect(jsonData.capacity).to.eql(513);
});
